#define main old_main
#include "s61_binary_hyperplane_modular_determinants_20261102.cpp"
#undef main
vector<Factor> load(const char*path){ifstream in(path);assert(in);string s;int mi,n;in>>s>>mi>>s>>n;vector<Factor>b;for(int i=0;i<n;i++){int m;in>>s>>m;Poly p;read(in,p);b.push_back(Factor{p,m});}return b;}
int main(int argc,char**argv){assert(argc==4);ofstream out(argv[3]);assert(out);prime=32003;nmod_mpoly_ctx_init(ctx,3,ORD_LEX,prime);{auto A=load(argv[1]),B=load(argv[2]);const char*vars[]={"a","e","d"};const char*known[]={"a","500*a+90*e^2+3*e-24","50*a*d+18*d*e^2-9*d*e-2*d+60*e-40","100*a+18*e^2-9*e-2"};vector<Poly>u(4);for(int j=0;j<4;j++)assert(!nmod_mpoly_set_str_pretty(u[j].p,known[j],vars,ctx));Poly q,g;for(auto*bag:{&A,&B})for(auto&f:*bag)for(auto&v:u)while(!nmod_mpoly_is_ui(f.p.p,ctx)&&nmod_mpoly_divides(q.p,f.p.p,v.p,ctx))f.p=q;int hits=0;for(int i=0;i<(int)A.size();i++)for(int j=0;j<(int)B.size();j++){if(nmod_mpoly_is_ui(A[i].p.p,ctx)||nmod_mpoly_is_ui(B[j].p.p,ctx))continue;assert(nmod_mpoly_gcd(g.p,A[i].p.p,B[j].p.p,ctx));if(!nmod_mpoly_is_ui(g.p,ctx)){out<<"HIT "<<i<<' '<<j<<' ';write(out,g);hits++;}}out<<"HITS "<<hits<<'\n';out.flush();assert(out.good());cerr<<"HITS "<<hits<<'\n';}nmod_mpoly_ctx_clear(ctx);flint_cleanup();}
